import SwiftUI

/// A fallback for WebGL/canvas games that listen for keyboard key events
/// rather than HTML input/change events generated by the iOS software keyboard.
struct GameKeyboardSheet: View {
    @Environment(\.dismiss) private var dismiss
    @State private var typed = ""
    @State private var replaceCurrent = true
    @State private var pressReturn = true

    let onSend: (String, Bool, Bool) -> Void

    var body: some View {
        NavigationStack {
            Form {
                Section("Game text") {
                    TextField("Username, chat message, or other text", text: $typed)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                        .submitLabel(.done)
                    Toggle("Clear existing game text first", isOn: $replaceCurrent)
                    Toggle("Send Enter to confirm", isOn: $pressReturn)
                }
                Section {
                    Text("First tap the text box inside the game, then use this helper. It sends keyboard events to the page for games that do not accept iPhone keyboard events. Normal website text fields should use the usual keyboard. Some games ignore synthetic keyboard events, so compatibility varies.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
            }
            .navigationTitle("Game keyboard")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Send") {
                        onSend(typed, replaceCurrent, pressReturn)
                        dismiss()
                    }
                    .disabled(typed.isEmpty)
                }
            }
        }
        .presentationDetents([.medium, .large])
    }
}
